{{--
  KÖZÖS függőleges görgető (a 2026-os lib/rail renderVScroll): a görgetett elem (data-vscroll="$id") MELLÉ kerül.
  A viselkedés: public/js/vrail.js, a kinézet: public/css/vrail.css. Paraméterek: $id, $cimke, $fel, $le (a gombok feliratai).
--}}
<div class="vrail" data-vscrollnav="{{ $id }}" hidden><button class="vrailarrow vrailup" type="button" aria-label="{{ $fel }}" disabled><svg viewBox="0 0 34 46" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 24 L17 14 L26 24"/><path d="M8 36 L17 26 L26 36"/><circle class="mk-dot" cx="17" cy="9" r="2.4" stroke="none"/></svg></button><div class="vrailline"><div class="vrailknob" role="slider" tabindex="0" aria-label="{{ $cimke }}" aria-orientation="vertical" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="14" class="mk-lime" fill="none" stroke-width="6"/><circle cx="20" cy="20" r="5" class="mk-yellow"/></svg></div></div><button class="vrailarrow vraildown" type="button" aria-label="{{ $le }}"><svg viewBox="0 0 34 46" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 22 L17 32 L26 22"/><path d="M8 10 L17 20 L26 10"/><circle class="mk-dot" cx="17" cy="37" r="2.4" stroke="none"/></svg></button></div>
